@layer ds.tokens, ds.expression;

/*
 * dooph Design System — Token Layer
 *
 * Theming contract:
 * — Light palette: `:root` and `.light` (same declarations). Default look for
 *   apps that omit theme classes or force `class="light"` (e.g. next-themes).
 * — Dark palette: `.dark` on the app root (typically `<html>`). Your theme
 *   provider decides when `.light` vs `.dark` applies (manual toggle, saved
 *   preference, three-way light/dark/system, etc.).
 * — There is NO `prefers-color-scheme` remapping here: system mode is the
 *   consuming app's job (providers add/remove `.dark` from OS preference).
 *
 * Authority — cascade layers, so precedence never depends on file order or
 * selector specificity. Everything below sits in two layers:
 *   ds.tokens      the DS defaults (light, dark, reduced motion)
 *   ds.expression  the expression presets ([data-ds-expression="…"])
 * A consuming app's own tokens.css is UNLAYERED, so it always wins:
 *   your tokens.css > the expression preset > DS defaults.
 * Override `--ui-*` there, targeting `:root` / `.light` / `.dark` as needed —
 * never hardcoded in components. Import order does not matter.
 *
 * Expression tokens: one per expressive DETAIL inside a practical component
 * (e.g. the dropdown caret's shape). Each line ends in an `expression`
 * marker comment, is read only through a `.ds-expr-*` helper, and has its
 * neutral value in the practical preset at the end of this file. Components
 * never set them.
 * Checked by the lint check "expression tokens set or read outside the
 * expression system".
 */

@layer ds.tokens {

:root,
.light {
  /* ── Colors ─────────────────────────────────────────────────────────── */

  /* Primary (dark neutral) — borders alias bg per state (Figma) */
  --ui-color-primary: #171717;
  --ui-color-primary-border: var(--ui-color-primary);
  --ui-color-primary-hover: #2c2c2c;
  --ui-color-primary-border-hover: var(--ui-color-primary-hover);
  --ui-color-primary-active: #3d3d3d;
  --ui-color-primary-border-active: var(--ui-color-primary-active);
  --ui-color-primary-foreground: #ffffff;
  /* Disabled paints alias secondary so all solid buttons share one disabled look;
   * token names stay so consumers can still override primary-disabled alone. */
  --ui-color-primary-disabled: var(--ui-color-secondary-disabled);
  --ui-color-primary-border-disabled: var(--ui-color-secondary-border-disabled);

  /* Secondary (light surface) — borders are distinct Figma literals */
  --ui-color-secondary: #fdfdfd;
  --ui-color-secondary-border: #e2e3e4;
  --ui-color-secondary-hover: #efefef;
  --ui-color-secondary-border-hover: #e2e3e4;
  --ui-color-secondary-active: #e3e3e3;
  --ui-color-secondary-border-active: #e2e3e4;
  --ui-color-secondary-foreground: #161616;
  --ui-color-secondary-disabled: #f5f5f5;
  --ui-color-secondary-border-disabled: #e9e9e9;

  /* Prominent (deep violet) — Figma ButtonProminent/*. Borders alias bg per
   * state. Its own paints are mode-invariant, so they have no .dark override
   * (the two disabled aliases are repeated in the .dark alias group): the
   * Figma group carries identical values in both modes, INCLUDING the
   * content colour. That last part is worth stating because the Figma export
   * aliases the content to Text/text-inverted, which flips to black in dark —
   * black on #340fd9 is 2.2:1 and unreadable, and the export's own resolved
   * values report white for both modes. White is the intended paint; do not
   * "fix" this into an inverted alias. */
  --ui-color-prominent: #340fd9;
  --ui-color-prominent-border: var(--ui-color-prominent);
  --ui-color-prominent-hover: #2406ac;
  --ui-color-prominent-border-hover: var(--ui-color-prominent-hover);
  --ui-color-prominent-active: #1a0189;
  --ui-color-prominent-border-active: var(--ui-color-prominent-active);
  --ui-color-prominent-foreground: #ffffff;
  /* Disabled aliases secondary, matching every other solid button (Figma). */
  --ui-color-prominent-disabled: var(--ui-color-secondary-disabled);
  --ui-color-prominent-border-disabled: var(
    --ui-color-secondary-border-disabled
  );

  /* Danger — the raw destructive palette (Figma danger-primary / -secondary).
   * Mode-invariant, so no .dark override. */
  --ui-color-danger-primary: #ea3f3f;
  --ui-color-danger-secondary: #ff5858;

  /* Danger button (Figma ButtonDanger/*) — a full state family so consumers can
   * retune the danger button without touching the secondary family it defaults
   * to. Every value is an ALIAS, so they follow the secondary family per mode;
   * they are repeated in the .dark alias group so nested `.dark` regions
   * re-resolve them. Override any one of them to break that link. */
  --ui-color-danger: var(--ui-color-secondary);
  --ui-color-danger-border: var(--ui-color-secondary-border);
  --ui-color-danger-hover: var(--ui-color-danger-secondary);
  --ui-color-danger-border-hover: var(--ui-color-danger-secondary);
  --ui-color-danger-active: var(--ui-color-danger-primary);
  --ui-color-danger-border-active: var(--ui-color-danger-primary);
  --ui-color-danger-foreground: var(--ui-color-danger-primary);
  --ui-color-danger-foreground-active: var(--ui-color-secondary-foreground);
  --ui-color-danger-disabled: var(--ui-color-secondary-disabled);
  --ui-color-danger-border-disabled: var(--ui-color-secondary-border-disabled);

  /* Ghost (no rest bg; hover/active are translucent overlays) */
  --ui-color-ghost-foreground: var(--ui-color-text);
  --ui-color-ghost-hover: rgba(0, 0, 0, 0.04);
  --ui-color-ghost-active: rgba(0, 0, 0, 0.08);
  --ui-color-ghost-foreground-active: #161616;

  /* Surfaces (Figma: surface-page / surface-primary / surface-secondary) */
  --ui-color-surface-page: #fdfeff;
  --ui-color-surface-primary: #ffffff;
  --ui-color-surface-secondary: #fcfcfc;

  /* Text selection (::selection). The package ships only the tokens — applying
     them is a global, app-owned decision; use the .ds-selection opt-in class or
     write your own ::selection rule.

     Aliased to the primary button pair, so a selection reads as a primary
     surface and follows a rebrand for free. Note this inverts with the palette
     (dark-on-light in light mode, light-on-dark in dark) because primary does;
     override both tokens if you need a fixed colour. Repeated in the .dark alias
     group so a nested .dark region re-resolves it. */
  --ui-color-selection: var(--ui-color-primary);
  --ui-color-selection-foreground: var(--ui-color-primary-foreground);

  /* Modals */
  --ui-color-modal-surface: #fdfdfd;
  --ui-color-modal-backdrop: rgba(0, 0, 0, 0.35);

  /* Tooltips */
  --ui-color-tooltip-inverse-surface: var(--ui-color-primary);
  --ui-color-tooltip-inverse-text: var(--ui-color-primary-foreground);
  --ui-color-tooltip-inverse-border: var(--ui-color-primary);
  --ui-color-tooltip-matching-surface: var(--ui-color-secondary);
  --ui-color-tooltip-matching-text: var(--ui-color-secondary-foreground);
  --ui-color-tooltip-matching-border: var(--ui-color-border-primary);

  /* Borders (Figma: border-primary / border-secondary; popovers is the DS name
   * for Figma modal-border, shared by modal/menu/toast panels) */
  --ui-color-border-primary: #dddddd;
  --ui-color-border-secondary: #dfdfdf;
  --ui-color-border-popovers: #ebebeb;
  --ui-color-input-border-focus: var(--ui-color-prominent-border-hover);
  /* CTAButton padded outline ring (primary variant only) */
  --ui-color-border-cta: rgba(56, 56, 56, 0.5);
  --ui-color-input-border-hover: #b4b4b4;
  --ui-color-input-border-danger-focus: var(--ui-color-danger-primary);

  /* Text */
  --ui-color-text: #161616;
  --ui-color-text-secondary: #4a4a4a;
  --ui-color-text-tertiary: #606060;

  /* Focus rings (Figma: Inputs/focus-ring-prominent|-primary|-danger). Each is
   * its source paint at a fixed alpha: prominent = button-prominent-hover in
   * light and button-prominent (rest) in dark, primary = button-primary,
   * danger = danger-primary. They are literal rgba() rather than color-mix()
   * over the source token because a consumer overriding, say,
   * --ui-color-prominent should be able to retune the ring independently. */
  /* Focus-ring outline width (Figma buttonSizes/focus-ring-spread), and the small
   * step for compact controls such as Checkbox, where 4px reads as huge. */
  --ui-focus-ring-width: 4px;
  --ui-focus-ring-width-sm: 2px;
  --ui-color-focus-ring-prominent: rgba(36, 6, 172, 0.35);
  --ui-color-focus-ring-primary: rgba(23, 23, 23, 0.25);
  --ui-color-focus-ring-danger: rgba(234, 63, 63, 0.35);

  /* Prominent identity (Figma: color-prominent / -alt / -ter) — the
   * brand-identity trio, distinct from the --ui-color-prominent BUTTON family
   * above. All three are mode-invariant: none has a dark value, and #44c0e5
   * is `-ter` in its own right, not a dark `-alt`. */
  --ui-prominent-color: #390ef8;
  --ui-prominent-color-alt: #13c29f;
  --ui-prominent-color-ter: #44c0e5;

  /* AI model marks (Figma ai-models/*). Brand colours for third-party model
   * providers — identity paints for a badge or icon, not a UI role, so no
   * component reads them by default. openai and spacexai are the two that
   * inverse per mode. */
  --ui-color-ai-anthropic: #e48844;
  --ui-color-ai-gemini: #154bff;
  --ui-color-ai-openai: #000000;
  --ui-color-ai-spacexai: #000000;

  /* ── Motion ──────────────────────────────────────────────────────────────
   * One scale for the whole system: every transition and animation in the
   * package reads a duration and a curve from here, so retuning one token
   * retunes that step everywhere. Components consume it through the ds-motion-*
   * helpers and through var() inside CSS helpers — never through duration-N /
   * ease-* utilities or inline timing. A component keeps a motion token of its
   * own only when the value cannot sit on the scale: loops, staggers and the
   * generated shape-morph spring. Reduced motion is the single
   * `prefers-reduced-motion` block at the end of this file.
   *
   *   fast    — state feedback (hover, press, focus colour); small overlays in
   *             and out (menu, tooltip, popover, toast); quick swaps.
   *   base    — large overlay in and out (modal in, sheet out); disclosure;
   *             content swap out; small transforms.
   *   slow    — content swap in; sheet in; progress fills.
   *   slower  — reveals; chat streaming.
   *   slowest — expressive hover (underline link). */
  --ui-motion-duration-fast: 150ms;
  --ui-motion-duration-base: 200ms;
  --ui-motion-duration-slow: 300ms;
  --ui-motion-duration-slower: 420ms;
  --ui-motion-duration-slowest: 600ms;
  /*   standard — starts and ends on screen: state feedback, fades, progress.
   *   enter    — the house curve: entering, swapping in, expressive moves,
   *              glides. A long deceleration that settles.
   *   exit     — leaving: overlay exits, swap out. Accelerates away.
   *   linear   — loops (spinners, shimmer). */
  --ui-motion-ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
  --ui-motion-ease-enter: cubic-bezier(0.32, 0.72, 0, 1);
  --ui-motion-ease-exit: cubic-bezier(0.4, 0, 1, 1);
  --ui-motion-ease-linear: linear;
  /* Loop cycle times are not transitions, so they sit off the scale and are
   * NOT collapsed under reduced motion — each loop's own reduce rule stops it
   * or swaps in a static frame instead. */
  --ui-shimmer-duration: 2000ms;
  /* LoadingSpinner. `duration` is one flat-arc dash cycle (Material's
   * circular indeterminate: the arc grows, then its tail chases the head
   * round and it shrinks to a dot). `rotate-duration` is one constant turn of
   * the flat variant's arc group, a separate loop. Both are Material's
   * 1.4s. `spokes-duration` is one turn of the spokes and star variants at
   * the `rg` size; the component scales it per size by a geometry factor, so
   * retuning this retunes all four sizes together. */
  --ui-spinner-duration: 1400ms;
  --ui-spinner-rotate-duration: 1400ms;
  --ui-spinner-spokes-duration: 1800ms;

  /* Text shimmer (ShimmerText) */
  --ui-shimmer-base: var(--ui-color-text-tertiary);
  --ui-shimmer-highlight: color-mix(
    in srgb,
    var(--ui-color-text-tertiary) 35%,
    transparent
  );

  /* AI chat parts (AIToolPart, AIThinkingPart, AITurnSummary, AIPromptInput…).
   *
   * The two shimmer pairs RE-BASE ShimmerText rather than restyling it: a
   * working tool row reads at full ghost-active weight, the thinking row at the
   * quieter text-secondary weight, the colour a settled thinking label rests at
   * (Figma 761:1330 / 761:1346). The highlight keeps the
   * package's own base-at-35% formula so a consumer retuning either base keeps
   * the sheen in proportion. */
  --ui-chat-tool-shimmer-base: var(--ui-color-ghost-foreground-active);
  --ui-chat-tool-shimmer-highlight: color-mix(
    in srgb,
    var(--ui-color-ghost-foreground-active) 35%,
    transparent
  );
  --ui-chat-thinking-shimmer-base: var(--ui-color-text-secondary);
  --ui-chat-thinking-shimmer-highlight: color-mix(
    in srgb,
    var(--ui-color-text-secondary) 35%,
    transparent
  );
  /* `streamingAnimation`: each block of prose rises out of a blur as it
   * arrives. `blur` is px on purpose — a lens effect, not a typographic
   * measure (the roll's blur, --ui-roll-change-blur, is em because it must
   * stay inside a clip box that scales with the type). Its timing, like the
   * hover reveal's and the transcript disclosure's, is on the motion scale. */
  --ui-chat-stream-blur: 3px;
  --ui-chat-stream-rise: 4px;
  /* The prompt textarea grows with its content up to this, then scrolls. CSS
   * max-height applies the cap and the component only sets height =
   * scrollHeight, so this token is the only place the cap lives. */
  --ui-chat-prompt-max-height: 300px;
  /* The provider swatch in AIModelSelectItem (Figma 761:2073). */
  --ui-chat-model-swatch-size: 10px;
  --ui-chat-model-swatch-radius: 3px;
  /* AIModelTooltipContent panel (Figma 761:2843). */
  --ui-width-chat-model-tooltip: 242px;
  /* Inline code inside ds-chat-prose. */
  --ui-chat-prose-code-radius: 4px;
  /* Links and blockquotes inside ds-chat-prose. */
  --ui-chat-prose-link-offset: 3px;
  --ui-chat-prose-quote-border-width: 2px;

  /* Text roll on hover (RollHoverText). Each letter rolls over
   * --ui-motion-duration-slower; the duration:stagger ratio (~1:12) is what
   * makes the letters read as one travelling wave instead of a metronome —
   * raising the stagger toward the duration turns it into discrete flips. */
  --ui-roll-hover-stagger: 35ms;
  --ui-roll-hover-blur: 3px;
  --ui-roll-hover-depth: 0.5em;
  /* Both in em so depth/perspective stays constant at every font size — the
   * ratio is what governs how 3D the roll reads, and a px perspective would
   * make the same component subtle in a button and overdone in a hero. */
  --ui-roll-hover-perspective: 10em;

  /* Text roll on change (RollChangeText). Timing is on the motion scale: the
   * old content leaves over `base` on the accelerating `exit` curve (it is
   * being thrown away, so it should not linger) while the new content arrives
   * over `slow` on the decelerating `enter` curve and settles. Giving the two
   * halves one shared ease flattens that read.
   *
   * `depth` is in em so the travel scales with the type, like the hover roll's.
   * `blur` is in em too (~0.1em, 1.6px at 16px): a fixed 4px halo outgrew small
   * type and was sliced at the clip edge mid-roll. The in-animation's mid-point
   * blur is derived from this token, not a second one, so the two stay in
   * proportion.
   *
   * `breathe` is the vertical room the clip box gets above and below the line
   * (padding, cancelled by an equal negative margin so layout does not move)
   * so the soft mask fades the blur halo instead of cutting it.
   *
   * The exiting node is unmounted by its own `animationend`, so nothing in the
   * component mirrors the out duration: a JS setTimeout copying it would
   * desync the moment either side is retuned. */
  --ui-roll-change-depth: 0.55em;
  --ui-roll-change-blur: 0.1em;
  --ui-roll-change-breathe: 0.15em;

  /* Fade-roll on change (FadeChangeText) — the roll above without the blur:
   * travel + opacity only, on the same motion-scale timing. The depth ALIASES
   * the roll's, so the two stay one motion by default and either can be
   * retuned alone. */
  --ui-fade-change-depth: var(--ui-roll-change-depth);

  /* Shape morph — MorphRotationShape / ShapeMorphSpinner.
   * duration + ease are GENERATED by scripts/generate-shape-morph-ease.mjs
   * from the tuned spring in scripts/shapeMorphSpring.mjs. Edit the constants
   * there and run `npm run generate-shape-morph-ease`, never these two lines.
   * The ease overshoots (~1.095) on purpose: that is the morph's backspin. */
  /* __SHAPE_MORPH_EASE_START__ */
  --ui-shape-morph-duration: 498ms;
  --ui-shape-morph-ease: linear(0, 0.0058 1.56%, 0.0221 3.13%, 0.0475 4.69%, 0.0805 6.25%, 0.1198 7.81%, 0.1643 9.38%, 0.2127 10.94%, 0.2640 12.50%, 0.3173 14.06%, 0.3718 15.63%, 0.4266 17.19%, 0.4811 18.75%, 0.5348 20.31%, 0.5871 21.88%, 0.6376 23.44%, 0.6860 25.00%, 0.7319 26.56%, 0.7752 28.13%, 0.8157 29.69%, 0.8533 31.25%, 0.8878 32.81%, 0.9194 34.38%, 0.9480 35.94%, 0.9736 37.50%, 0.9964 39.06%, 1.0164 40.63%, 1.0337 42.19%, 1.0486 43.75%, 1.0610 45.31%, 1.0712 46.88%, 1.0793 48.44%, 1.0856 50.00%, 1.0901 51.56%, 1.0930 53.13%, 1.0945 54.69%, 1.0947 56.25%, 1.0939 57.81%, 1.0921 59.38%, 1.0895 60.94%, 1.0865 62.50%, 1.0832 64.06%, 1.0795 65.63%, 1.0755 67.19%, 1.0713 68.75%, 1.0669 70.31%, 1.0623 71.88%, 1.0576 73.44%, 1.0528 75.00%, 1.0480 76.56%, 1.0432 78.13%, 1.0384 79.69%, 1.0338 81.25%, 1.0292 82.81%, 1.0249 84.38%, 1.0207 85.94%, 1.0168 87.50%, 1.0132 89.06%, 1.0100 90.63%, 1.0071 92.19%, 1.0047 93.75%, 1.0027 95.31%, 1.0012 96.88%, 1.0003 98.44%, 1 100%);
  /* __SHAPE_MORPH_EASE_END__ */
  --ui-shape-morph-interval: 650ms;
  --ui-shape-morph-passive-spin-duration: 4666ms;

  /* Hover nudge: how far a hovered shape leans toward the next stop (a
   * fraction of one step, applied to morph AND turn). The lean is timed on the
   * motion scale (`base`, `enter`) — gentle and non-overshooting, so hovering
   * never wobbles. */
  --ui-shape-morph-nudge: 0.15;

  /* Rolling digits (RollingDigitsText) — 2D cash-register snap, not 3D.
   *
   * Timing is on the motion scale, all on the `enter` curve. The ROLL — a
   * wheel already on screen translating to its new digit — runs over `base`.
   * `stagger` defaults to zero so every wheel starts and lands together, one
   * snap for the whole figure; it stays a token so a consumer can dial in a
   * right-to-left cascade (ones place leads) without patching the package.
   *
   * A whole SLOT — a wheel or a grouping separator — opens from zero width
   * over `slow` and collapses to zero width over `base`, fading as it goes.
   * Width and opacity are the same animation, and it runs CONCURRENTLY with
   * the roll of the wheels already on screen. `opacity-ratio` is the FRACTION
   * of that duration the fade occupies: opacity finishes early so an arriving
   * glyph (which is drawn at full 1ch and overflows its narrower slot) is
   * already opaque by the time it stops overlapping its neighbour.
   *
   * `digit-width` and `separator-width` are the two slot widths. Both have to
   * be fixed lengths because `width` cannot animate from `auto`, and both are
   * relative units so the figure scales with its type.
   *
   * `digit-width` defaults to 1ch, which is the advance of "0" — very close to,
   * but not exactly, the TABULAR advance the figure actually renders at (Google
   * Sans Flex: 1ch is about 2% under). Every wheel is centred in its own slot,
   * so the error is symmetric per digit rather than cumulative, and the only
   * visible effect is a figure fractionally tighter than the same string set as
   * plain text. Retune this if a consumer's face drifts further.
   *
   * `separator-width` is measured to the default face's comma. Too narrow only
   * means the glyph is optically tight — the separator does not clip, because
   * its overflow is visible and its glyph is centred.
   *
   * `decimals-size` / `decimals-rise` / `decimals-gap` are all in em of the
   * PARENT — the integer part — not of the decimals. That is what keeps the
   * decimals a fixed PROPORTION of the figure at every size: a role passed as
   * `smallDecimalsComponent` carries its own absolute font size (LabelText is a
   * flat 12px), which would read correctly beside 23px integers and far too
   * small beside 40px ones. So these tokens own the size and the passed role
   * owns family, weight and tracking — applied by the
   * `.ds-rolling-digits-decimals > *` rule in index.css, which sizes the CHILD
   * precisely so the wrapper keeps inheriting the parent's em and `rise`/`gap`
   * stay measured against it. Override `decimals-size` to change the
   * proportion; `decimals-rise` needs re-tuning alongside it, since top-aligning
   * a taller decimals box takes less rise. */
  --ui-rolling-digits-stagger: 0ms;
  --ui-rolling-digits-opacity-ratio: 0.55;
  --ui-rolling-digits-digit-width: 1ch;
  --ui-rolling-digits-separator-width: 0.34em;
  --ui-rolling-digits-decimals-size: 0.5em;
  --ui-rolling-digits-decimals-rise: 0.525em;
  --ui-rolling-digits-decimals-gap: 0.06em;

  /* Text underline link wipe (UnderlineLinkText). On hover the line sweeps out
   * to the right then redraws in from the left. Thickness/offset are in em so the
   * underline scales with the text. The line is positioned at
   * `calc(1em + offset)` from the top of each line box — just under the em
   * square, like a native text-decoration underline — rather than at the bottom
   * of the line box (which drifts with leading). Positive offset pushes further
   * down; 0 sits at the em-square bottom; negative pulls into the glyphs. The
   * sweep is timed on the motion scale (`slowest`, `enter`). */
  --ui-underline-link-thickness: 0.08em;
  --ui-underline-link-offset: 0.05em;

  /* ── Typography ──────────────────────────────────────────────────────── */

  /* Font family contract — one token per text role. Consumers load fonts and
   * may override any role independently (e.g. only buttons in a display face). */
  --ui-font-body: "Google Sans Flex", system-ui, sans-serif;
  --ui-font-button: "Google Sans Flex", system-ui, sans-serif;
  --ui-font-heading: "Google Sans Flex", system-ui, sans-serif;
  --ui-font-label: "Host Grotesk", system-ui, sans-serif;
  --ui-font-title: "Bricolage Grotesque", system-ui, sans-serif;
  --ui-font-hero: "Bricolage Grotesque", system-ui, sans-serif;
  /* The mono role deliberately falls back to the platform's UI monospace face
   * rather than to `monospace`, whose browser default is both smaller than the
   * surrounding text and, on Windows, Courier New. */
  --ui-font-mono:
    "Google Sans Code", ui-monospace, "SF Mono", SFMono-Regular, Menlo,
    Consolas, monospace;

  /* Font sizes */
  --ui-text-label: 12px;
  --ui-text-body: 14px;
  /* The hero-scale pair. `heroBody` and `heroButton` are the body and button
   * roles at a larger size and NOTHING else: family, weight, tracking and
   * variable axes all still come from --ui-font-body / --ui-font-button, so
   * retuning a base role carries its hero-scale twin with it. Only the size is
   * its own, which is the entire reason these roles exist. Independent
   * literals rather than one shared token, so either can be retuned alone. */
  --ui-text-hero-body: 16px;
  --ui-text-hero-button: 16px;
  /* Mono matches the button role's size and weight by aliasing them, so a
   * consumer who retunes button type keeps mono in step; override either token
   * directly to break that link. */
  --ui-text-mono: var(--ui-text-body);
  --ui-text-subheading: 18px;
  /* The verification-code digit (CodeDigitInput, `text-code-digit`). 18px like
   * subheading, but not that role, so it is its own token. */
  --ui-text-code-digit: 18px;
  --ui-text-heading: 20px;
  --ui-text-title: 40px;
  --ui-text-hero: 55px;

  /* Font weights — by role */
  --ui-weight-body: 400;
  --ui-weight-button: 500;
  --ui-weight-label: var(--ui-weight-regular);
  --ui-weight-subheading: var(--ui-weight-heading);
  --ui-weight-heading: 600;
  --ui-weight-title: 700;
  --ui-weight-hero: 700;
  --ui-weight-mono: var(--ui-weight-button);
  /* Hero CTA label: the button role, semibold. */
  --ui-weight-cta: var(--ui-weight-semibold);

  /* Font weights — by name (BaseText `fontWeight` prop; consumer-overridable) */
  --ui-weight-regular: 400;
  --ui-weight-medium: 500;
  --ui-weight-semibold: 600;
  --ui-weight-bold: 700;

  /* Variable font axes for Google Sans Flex text styles */
  --ui-font-var-button: "wdth" 100, "GRAD" 11, "ROND" 100, "slnt" 0;
  --ui-font-var-body: "wdth" 100, "GRAD" 19, "ROND" 100, "slnt" 0;
  --ui-font-var-heading: "wdth" 100, "GRAD" 11, "ROND" 100, "slnt" 0;
  /* Google Sans Code ships a MONO axis: 0 is its proportional cut, 1 the fixed
   * pitch one. Naming it here rather than trusting the family default is what
   * guarantees fixed advances, which is the entire point of the role. A face
   * without the axis ignores it silently. */
  --ui-font-var-mono: "MONO" 1;

  /* Letter spacing */
  --ui-tracking-body: 0.01em;
  --ui-tracking-label: 0;
  --ui-tracking-hero: -0.01em;
  /* Figma "Mono Text" style: -3%. Tightens Google Sans Code's fixed advances
   * to sit with the button role beside it; every glyph still shares one
   * advance, so figures stay aligned. */
  --ui-tracking-mono: -0.03em;

  /* ── Sizing ──────────────────────────────────────────────────────────── */

  --ui-height-button: 38px;
  --ui-height-button-sm: 34px;
  --ui-height-button-medium: 46px;
  --ui-height-button-big: 54px;
  /* Horizontal padding of the pill-shaped medium / big buttons. Figma draws
   * them as raw 22 / 32px, off the spacing scale, so they are their own
   * tokens. Raw var() inside the ds-px-button-* helpers only. */
  --ui-spacing-button-medium-x: 22px;
  --ui-spacing-button-big-x: 32px;
  /* Micro (28px): micro buttons, icon-micro toggles/tabs, and the compact preset row. */
  --ui-height-button-micro: 28px;
  --ui-size-checkbox: 18px;
  /* The check / indeterminate glyph box inside the checkbox (`.size-checkbox-icon`). */
  --ui-size-checkbox-icon: 10px;
  --ui-size-code-digit: 46px;
  /* Avatar frame per size (`.size-avatar` / `.size-avatar-sm`). */
  --ui-size-avatar: 38px;
  --ui-size-avatar-sm: 22px;
  /* ShapeButton frame AND the shape drawn in it (`.size-shape-button`, plus
   * the shape's `size` prop) — one token, so the two cannot drift apart. */
  --ui-size-shape-button: 46px;
  /* Floor of a single-key HotkeyIndicator, so a one-glyph key stays square
   * (`.ds-min-size-kbd`). */
  --ui-size-kbd: 23px;
  /* DropdownMenuLabel row height (`.h-menu-label`). */
  --ui-height-menu-label: 30px;
  /* TextDropdownTrigger (standard) height. Same row height as the menu label
   * by design; own name so either retunes alone (`.h-text-trigger`). */
  --ui-height-text-trigger: var(--ui-height-menu-label);
  /* LinearProgressIndicator bar height (`.h-linear-progress`). */
  --ui-height-linear-progress: 4px;

  /* Loading spinner / progress indicator diameters */
  --ui-size-spinner-sm: 16px;
  --ui-size-spinner-rg: 22px;
  --ui-size-spinner-md: 32px;
  --ui-size-spinner-xl: 40px;
  /* Toast widths — pinned per layout variant (capped to the container so a
   * narrow viewport can't overflow). */
  --ui-width-toast-simple: 230px;
  --ui-width-toast-complex: 360px;
  --ui-width-toast-viewport: var(--ui-width-toast-complex);

  /* Tooltip widths — the simple variant is intentionally hug (no token):
   * it sets whitespace-nowrap and sizes to its content. */
  --ui-width-tooltip-rich: 175px;
  --ui-min-w-tooltip-complex: 242px;

  /* Calendar — presets rail width and panel min-width (the day-cell radius is
   * with the radii, --ui-radius-calendar-day). */
  --ui-width-calendar-presets: 144px;
  /* Panel width sets the day-cell size: cells are aspect-square across seven
   * equal columns, so widening the panel makes each day physically bigger. */
  --ui-min-w-calendar-panel: 300px;
  --ui-height-slider-track: 22px;
  --ui-radius-slider-inner: 8px;
  --ui-slider-track-gap: 6px;
  --ui-width-slider-handle: 6px;
  --ui-height-slider-handle: 42px;
  /* Stepped slider step marks (Figma "Slider Step"). Every step is a round dot
   * of --ui-size-slider-step; the one a slider's `highlightedStep` picks keeps
   * that width and grows to --ui-height-slider-step-tall, a capsule centred on
   * the same point. 10px is the maintainer's call: Figma draws a 12px pill
   * overflowing a 10px frame, which is a mistake. Raw var() inside the
   * .ds-slider-dot helper only, never a utility. */
  --ui-size-slider-step: 6px;
  --ui-height-slider-step-tall: 10px;

  /* Slider paints (Figma SliderPrimary/* and SliderProminent/*).
   *
   * The ACTIVE TRACK is an OPACITY, not a colour, and that is deliberate: the
   * track is tinted from the component's `color` prop, which accepts any CSS
   * colour, so baking Figma's resolved rgba() here would stop a provider brand
   * colour from tinting the fill at all. Figma composes each variant's track
   * from its own button paint at a fixed alpha; we keep the alpha and let
   * `color` supply the hue, which reproduces both variants exactly when `color`
   * is the matching token and still works for an arbitrary colour.
   *
   * The ACTIVE STEP dot is a real colour, because Figma composes it from the
   * TEXT/content paint rather than from the slider's own hue — it is the mark
   * read ON the filled track, so it does not follow `color`.
   *
   * Each pair is selected by `SliderVariant`; `color` still overrides the hue
   * on top of whichever pair is in play.
   *
   * The prominent dark step is white, departing from the Figma export, which
   * resolves it to text-inverted = black. Black at 40% on a #340fd9 track is
   * invisible; see the note on the prominent family above for why that content
   * alias is white in both modes. */
  --ui-slider-track-primary-active-opacity: 50%;
  --ui-slider-track-prominent-active-opacity: 70%;
  --ui-color-slider-step-primary-active: rgba(22, 22, 22, 0.5);
  --ui-color-slider-step-prominent-active: rgba(22, 22, 22, 0.6);
  --ui-color-slider-step-inactive: var(--ui-color-secondary-border);

  /* ── Spacing ─────────────────────────────────────────────────────────── */

  --ui-spacing-xxxs: 2px;
  --ui-spacing-xxs: 4px;
  --ui-spacing-xs: 6px;
  --ui-spacing-sm: 8px;
  --ui-spacing-rg: 10px;
  --ui-spacing-md: 12px;
  --ui-spacing-lg: 16px;
  --ui-spacing-xl: 20px;
  --ui-spacing-xxl: 26px;
  --ui-spacing-xxxl: 42px;
  /* Complex toast top/left inset (Figma), off the spacing scale like
   * sticker-y (`pl-toast-inset` / `pt-toast-inset`). */
  --ui-spacing-toast-inset: 14px;
  /* TablePlaceholder (empty-state row) vertical padding, off the scale
   * (`py-table-placeholder-y`). */
  --ui-spacing-table-placeholder-y: 32px;

  /* ── Icons ───────────────────────────────────────────────────────────── */

  --ui-icon-sm: 12px;
  --ui-icon-rg: 14px;
  --ui-icon-md: 16px;
  --ui-icon-lg: 18px;
  --ui-icon-stroke-width: 2;

  /* ── Radius (semantic corners) ────────────────────────────────────────────
   * tight  — compact chrome: buttons, tabs, dense controls (kbd, etc.).
   * mini   — micro (28px) toggle options / tabs.
   * normal — triggers, grouped inputs, dropdown rows, segmented shells.
   * soft   — panels: modals, menu surfaces, search field shell, Outline inner.
   */
  --ui-radius-tight: 12px;
  /* Figma `radius-mini` — micro (28px) toggle options / tabs. */
  --ui-radius-mini: 10px;
  --ui-radius-normal: 18px;
  --ui-radius-soft: 20px;
  /* Concentric outer radius of the outline frame wrapping a `soft` surface
   * with an sm inset: soft (20) + sm (8) = 28px (`rounded-outline-frame`;
   * OutlineSection, OutlineButton). Override the parts, or this to break it. */
  --ui-radius-outline-frame: calc(var(--ui-radius-soft) + var(--ui-spacing-sm));
  --ui-radius-checkbox: 6px;
  --ui-radius-avatar: 8px;
  --ui-radius-avatar-sm: 6px;
  --ui-radius-calendar-day: 8px;

  /* ── Shadows ─────────────────────────────────────────────────────────── */

  --ui-shadow-button: 0 1px 2px rgba(0, 0, 0, 0.1);
  --ui-shadow-button-secondary: 0 1px 4px rgba(0, 0, 0, 0.1);
  --ui-shadow-button-hover: 0 1px 2px rgba(0, 0, 0, 0.2);
  /* defaults to hover shadow — kept as a separate token for manual override */
  --ui-shadow-button-active: 0 1px 2px rgba(0, 0, 0, 0.2);
  --ui-shadow-menu: 0 1px 4px 0 rgba(56, 56, 56, 0.15);
  /* Figma "Shadow Standard" — a soft all-round halo (UserMessageHeader). */
  --ui-shadow-standard: 0 0 4px 0 rgba(56, 56, 56, 0.1);
  --ui-shadow-cta: 0 1px 2px rgba(56, 56, 56, 0.15);
  --ui-shadow-focus-prominent: 0 0 0 4px var(--ui-color-focus-ring-prominent);
  --ui-shadow-focus-primary: 0 0 0 4px var(--ui-color-focus-ring-primary);
  --ui-shadow-focus-danger: 0 0 0 4px var(--ui-color-focus-ring-danger);
  /* Checkbox press ring (Figma active state) — the focus-ring paint, named for
   * its job so component classes never use a focus shadow for a press. */
  --ui-shadow-press-prominent: var(--ui-shadow-focus-prominent);
  --ui-shadow-press-primary: var(--ui-shadow-focus-primary);

  /* ── Menu min-widths ─────────────────────────────────────────────────── */

  --ui-min-w-menu: 160px;
  --ui-min-w-menu-complex: 324px;
  /* The standalone search field is the same width as a complex menu by
   * design, so it ALIASES that token rather than repeating the number —
   * but it keeps its own name, so a consumer can widen the search field
   * without touching menus. Same arrangement as primary-disabled. */
  --ui-min-w-search-box: var(--ui-min-w-menu-complex);

  /* ── OutlineButton ─────────────────────────────────────────────────────
   * The inner button box, and its two glow orbs. Orb 1 paints `glowColor1`
   * (the larger, left one), orb 2 `glowColor2`. Read by the
   * .ds-size-outline-button / .ds-outline-button-glow-* / -trail-* helpers.
   * The hover (cursor-tracking) mode blurs each orb 2px more than the static
   * `glowing` mode; that split predates the tokens and is kept as-is. Orb
   * timing is NOT here: it is on the motion scale (.ds-outline-orb-*). */
  --ui-height-outline-button: 54px;
  --ui-min-w-outline-button: 160px;
  --ui-outline-button-orb-1-opacity: 0.38;
  --ui-outline-button-orb-2-opacity: 0.22;
  --ui-outline-button-orb-1-blur: 18px;
  --ui-outline-button-orb-2-blur: 24px;
  --ui-outline-button-orb-1-hover-blur: 20px;
  --ui-outline-button-orb-2-hover-blur: 26px;
  /* Orb size, as a share of the button box (both modes). */
  --ui-outline-button-orb-1-width: 62%;
  --ui-outline-button-orb-1-height: 72%;
  --ui-outline-button-orb-2-width: 48%;
  --ui-outline-button-orb-2-height: 64%;
  /* `glowing` mode anchors: each orb hangs below the bottom edge, orb 1 in
   * from the left, orb 2 in from the right. */
  --ui-outline-button-orb-1-bottom: -18px;
  --ui-outline-button-orb-1-left: 4%;
  --ui-outline-button-orb-2-bottom: -14px;
  --ui-outline-button-orb-2-right: 6%;

  /* ── CTAButton ───────────────────────────────────────────────────────── */

  /* Label sizes, read by `.text-style-cta` (standard) and the big CTA. */
  --ui-text-cta-standard: 24px;
  --ui-text-cta-big: 28px;
  /* End-mark frame per size. */
  --ui-size-cta-chip-standard: 46px;
  --ui-size-cta-chip-big: 60px;
  /* The FIXED shape drawn in that frame (eight-leaf clover at standard, puff at
   * big). The clover fills its frame, so it aliases it; the puff sits 5px
   * inside the big frame (Figma: a 50px puff in a 60px frame). */
  --ui-size-cta-shape-standard: var(--ui-size-cta-chip-standard);
  --ui-size-cta-shape-big: var(--ui-size-cta-chip-big);
  /* Icon centred on the shape, per size. */
  --ui-size-cta-icon-standard: 22px;
  --ui-size-cta-icon-big: 26px;
  --ui-min-w-cta-content-standard: 330px;
  --ui-min-w-cta-content-big: 350px;
  /* Label → end-mark gap. Both sizes hug their content with the same 60px gap;
   * one token per size so either can be retuned alone. */
  --ui-spacing-cta-content-standard: 60px;
  --ui-spacing-cta-content-big: 60px;

  /* ── Stickers ──────────────────────────────────────────────────────────
   * Figma collection Colors - Statics, group `stickers/`.
   *
   * Content colours alias the paint Figma aliases, so retuning that paint
   * retunes the sticker. Backgrounds are a SEPARATE hue at an opacity: most
   * variants share the content hue, but secondary's wash is the secondary
   * button's active border and danger's wash is danger-secondary (the content
   * is danger-primary). The opacity stays its own token so `StickerVariant.custom`
   * can tint an arbitrary colour with it — baking the alpha into the hex would
   * freeze that.
   *
   * Figma spells the shared opacity `sticker-bg-opactity` (missing i). The
   * token uses the corrected spelling. */

  --ui-color-sticker-prominent: var(--ui-color-prominent);
  --ui-color-sticker-secondary: var(--ui-color-text-tertiary);
  --ui-color-sticker-alternate: var(--ui-prominent-color-alt);
  --ui-color-sticker-tertiary: var(--ui-prominent-color-ter);
  --ui-color-sticker-danger: var(--ui-color-danger-primary);

  --ui-sticker-bg-opacity: 20%;
  --ui-sticker-bg-opacity-secondary: 80%;

  --ui-color-sticker-bg-prominent: color-mix(
    in srgb,
    var(--ui-color-prominent) var(--ui-sticker-bg-opacity),
    transparent
  );
  --ui-color-sticker-bg-secondary: color-mix(
    in srgb,
    var(--ui-color-secondary-border-active)
      var(--ui-sticker-bg-opacity-secondary),
    transparent
  );
  --ui-color-sticker-bg-alternate: color-mix(
    in srgb,
    var(--ui-prominent-color-alt) var(--ui-sticker-bg-opacity),
    transparent
  );
  --ui-color-sticker-bg-tertiary: color-mix(
    in srgb,
    var(--ui-prominent-color-ter) var(--ui-sticker-bg-opacity),
    transparent
  );
  --ui-color-sticker-bg-danger: color-mix(
    in srgb,
    var(--ui-color-danger-secondary) var(--ui-sticker-bg-opacity),
    transparent
  );

  /* Figma's sticker vertical padding is a raw 6px, off the spacing scale. */
  --ui-spacing-sticker-y: 6px;

  /* ── Disabled ────────────────────────────────────────────────────────── */

  --ui-opacity-disabled: 0.6;
}

/* ── Dark mode — class on app root (<html>) · consuming app attaches/removes ─ */

.dark {
  --ui-color-primary: #f9f9f9;
  --ui-color-primary-foreground: #000000;
  --ui-color-primary-hover: #f0f0f0;
  --ui-color-primary-active: #cdcdcd;

  --ui-color-secondary: #1d1d1f;
  --ui-color-secondary-foreground: #ffffff;
  --ui-color-secondary-hover: #2b2b2d;
  --ui-color-secondary-active: #313235;
  --ui-color-secondary-disabled: #222224;
  --ui-color-secondary-border: #303235;
  --ui-color-secondary-border-hover: #313235;
  --ui-color-secondary-border-active: #3a3b3f;
  --ui-color-secondary-border-disabled: #1f1f21;

  --ui-color-ghost-hover: rgba(255, 255, 255, 0.04);
  --ui-color-ghost-active: rgba(255, 255, 255, 0.08);
  --ui-color-ghost-foreground: var(--ui-color-text);
  --ui-color-ghost-foreground-active: #ffffff;

  --ui-color-surface-page: #131c1d;
  --ui-color-surface-primary: #000000;
  --ui-color-surface-secondary: #242425;

  --ui-color-modal-surface: #212124;
  --ui-color-modal-backdrop: rgba(0, 0, 0, 0.7);

  --ui-color-border-primary: #333437;
  --ui-color-border-secondary: #3e3f42;
  --ui-color-border-popovers: #36363b;
  --ui-color-border-cta: rgba(255, 255, 255, 0.35);
  --ui-color-input-border-hover: #3a3b3f;

  --ui-color-ai-openai: #ffffff;
  --ui-color-ai-spacexai: #ffffff;

  --ui-color-text: #ffffff;
  --ui-color-text-secondary: #afafaf;
  /* PLACEHOLDER (2026-10-07), pending the maintainer's dark pass: light
   * enough to read at 3:1 or more on the menu hotkey chip (secondary-hover). */
  --ui-color-text-tertiary: #8b8b8b;

  /* The prominent ring keys to the rest paint (not :hover) in dark, per Figma. */
  --ui-color-focus-ring-prominent: rgba(52, 15, 217, 0.15);
  --ui-color-focus-ring-primary: rgba(249, 249, 249, 0.15);
  --ui-color-focus-ring-danger: rgba(234, 63, 63, 0.15);
  --ui-color-input-border-focus: var(--ui-color-prominent-border-active);

  --ui-shadow-button: 0 1px 2px rgba(0, 0, 0, 0.65);
  --ui-shadow-button-secondary: 0 1px 4px rgba(0, 0, 0, 0.65);
  --ui-shadow-button-hover: 0 1px 2px rgba(0, 0, 0, 0.85);
  --ui-shadow-button-active: 0 1px 2px rgba(0, 0, 0, 0.85);
  --ui-shadow-menu: 0 2px 8px rgba(0, 0, 0, 0.7);
  --ui-shadow-standard: 0 0 4px 0 rgba(0, 0, 0, 0.65);
  --ui-shadow-cta: 0 1px 2px rgba(0, 0, 0, 0.65);

  /* Both variants converge at 60% in dark, per Figma. */
  --ui-slider-track-primary-active-opacity: 60%;
  --ui-slider-track-prominent-active-opacity: 60%;
  --ui-color-slider-step-primary-active: rgba(0, 0, 0, 0.4);
  --ui-color-slider-step-prominent-active: rgba(255, 255, 255, 0.4);

  --ui-opacity-disabled: 0.5;

  /* The dark secondary WASH does not read --ui-sticker-bg-opacity-secondary
   * (80%, light only) — Figma binds `color-sticker-bg-secondary` to the shared
   * 20% opacity in dark.
   * Danger: PLACEHOLDER (2026-10-07), pending the maintainer's dark pass.
   * Figma's dark values, a literal white for both content and wash, make the
   * sticker invisible. So the content takes the lighter danger-secondary, and
   * the wash keeps the light formula (danger-secondary at the shared
   * opacity). */
  --ui-color-sticker-bg-secondary: color-mix(
    in srgb,
    var(--ui-color-secondary-border-active) var(--ui-sticker-bg-opacity),
    transparent
  );
  --ui-color-sticker-danger: var(--ui-color-danger-secondary);
  /* PLACEHOLDER (2026-10-07): the :root content, --ui-color-prominent
   * (#340fd9), reads at 1.75:1 on its own wash over dark surfaces, so dark
   * takes a lifted violet until the dark pass. */
  --ui-color-sticker-prominent: #8c7bff;

  /* ── Alias re-declarations ─────────────────────────────────────────────
   * A var() inside a custom property is resolved on the element that
   * DECLARES it. Under <html class="dark"> that is the same element as
   * :root, but a nested `.dark` region inherits an alias already resolved to
   * its LIGHT value unless `.dark` declares it again. So every :root alias
   * whose target changes in dark is repeated here, text identical to :root.
   * "Only lines whose value changes in dark" means the RESOLVED value, so do
   * not delete these as unchanged. Add a line whenever a new alias points at
   * a token this block overrides; the lint check "dark aliases missing from
   * .dark, and redundant .dark lines" reports any that are missing. */
  --ui-color-primary-border: var(--ui-color-primary);
  --ui-color-primary-border-hover: var(--ui-color-primary-hover);
  --ui-color-primary-border-active: var(--ui-color-primary-active);
  --ui-color-primary-disabled: var(--ui-color-secondary-disabled);
  --ui-color-primary-border-disabled: var(--ui-color-secondary-border-disabled);
  --ui-color-prominent-disabled: var(--ui-color-secondary-disabled);
  --ui-color-prominent-border-disabled: var(--ui-color-secondary-border-disabled);
  --ui-color-danger: var(--ui-color-secondary);
  --ui-color-danger-border: var(--ui-color-secondary-border);
  --ui-color-danger-foreground-active: var(--ui-color-secondary-foreground);
  --ui-color-danger-disabled: var(--ui-color-secondary-disabled);
  --ui-color-danger-border-disabled: var(--ui-color-secondary-border-disabled);
  --ui-color-selection: var(--ui-color-primary);
  --ui-color-selection-foreground: var(--ui-color-primary-foreground);
  --ui-color-tooltip-inverse-surface: var(--ui-color-primary);
  --ui-color-tooltip-inverse-text: var(--ui-color-primary-foreground);
  --ui-color-tooltip-inverse-border: var(--ui-color-primary);
  --ui-color-tooltip-matching-surface: var(--ui-color-secondary);
  --ui-color-tooltip-matching-text: var(--ui-color-secondary-foreground);
  --ui-color-tooltip-matching-border: var(--ui-color-border-primary);
  --ui-shimmer-base: var(--ui-color-text-tertiary);
  --ui-shimmer-highlight: color-mix(in srgb, var(--ui-color-text-tertiary) 35%, transparent);
  --ui-chat-tool-shimmer-base: var(--ui-color-ghost-foreground-active);
  --ui-chat-tool-shimmer-highlight: color-mix(in srgb, var(--ui-color-ghost-foreground-active) 35%, transparent);
  --ui-chat-thinking-shimmer-base: var(--ui-color-text-secondary);
  --ui-chat-thinking-shimmer-highlight: color-mix(in srgb, var(--ui-color-text-secondary) 35%, transparent);
  --ui-color-slider-step-inactive: var(--ui-color-secondary-border);
  --ui-shadow-focus-prominent: 0 0 0 4px var(--ui-color-focus-ring-prominent);
  --ui-shadow-focus-primary: 0 0 0 4px var(--ui-color-focus-ring-primary);
  --ui-shadow-focus-danger: 0 0 0 4px var(--ui-color-focus-ring-danger);
  --ui-shadow-press-prominent: var(--ui-shadow-focus-prominent);
  --ui-shadow-press-primary: var(--ui-shadow-focus-primary);
  --ui-color-sticker-secondary: var(--ui-color-text-tertiary);
}

/* ── Reduced motion — the ONE place it is handled ───────────────────────────
 * Every transition and animation in the package reads its duration from the
 * motion scale, so collapsing the scale here makes the whole system instant.
 * A component carries its own reduce rule only where this collapse cannot
 * reach: a loop or an off-scale duration (the shimmer, the spinners, the
 * shape-morph spring and the dropdown caret that rides it), or motion that
 * must become a static frame rather than a shorter one (RollHover).
 *
 * 1ms, NOT 0ms, and that is load-bearing: a 0ms transition never fires
 * `transitionrun` or `transitionend`, and several components hang real work
 * off those events (RevealChangeText swaps its content and calls `onSettled`
 * on `transitionend`; MorphRotationShape starts sampling on `transitionrun`).
 * At 0ms they would strand content on screen. 1ms reads as instant and still
 * fires every event.
 *
 * Staggers go to zero so nothing waits on a delay. Loop cycle times
 * (--ui-shimmer-duration, --ui-shape-morph-*) are deliberately absent: a loop
 * at 1ms would strobe, so each loop's own reduce rule stops it or shows a
 * static frame instead.
 *
 * `.light` is listed beside `:root` because it redeclares the scale; without
 * it a `.light` subtree would quietly restore full-length motion.
 *
 * `!important` is deliberate and load-bearing: these tokens live in
 * `@layer ds.tokens`, and a consumer's UNLAYERED override (e.g. a product
 * tuning --ui-motion-duration-fast) would otherwise beat this block and give
 * reduced-motion users full animations. A layered !important outranks every
 * unlayered normal declaration, so the user's accessibility setting always
 * wins. Do not remove it. */
@media (prefers-reduced-motion: reduce) {
  :root,
  .light {
    --ui-motion-duration-fast: 1ms !important;
    --ui-motion-duration-base: 1ms !important;
    --ui-motion-duration-slow: 1ms !important;
    --ui-motion-duration-slower: 1ms !important;
    --ui-motion-duration-slowest: 1ms !important;
    --ui-roll-hover-stagger: 0ms !important;
    --ui-rolling-digits-stagger: 0ms !important;
  }
}

/* ── Expression details — DS defaults (the signature look) ──────────────────
 * Declared on :root ONLY, not beside `.light`/`.dark`: a theme-class subtree
 * must never quietly restore a detail the practical preset turned off. */
:root {
  /* DropdownCaret shape: 1 = the morphing shape behind the chevron, in its
   * square; 0 = a plain chevron, no shape and no frame around it. Values in
   * between interpolate size and colour; 0 and 1 are the designed settings. */
  --ui-caret-shape-scale: 1; /* expression */
  /* DropdownCaret hover lean (a fraction of one step, like
   * --ui-shape-morph-nudge, which it follows by default); 0 = no lean. */
  --ui-caret-nudge: var(--ui-shape-morph-nudge); /* expression */
}

} /* @layer ds.tokens */

/* ── Expression presets ─────────────────────────────────────────────────────
 * A product-level setting: put the attribute on the root element —
 * `<html data-ds-expression="practical">` in a Next.js app/layout.tsx, or
 * index.html in Vite. Nesting works ("nearest ancestor wins") but is
 * discouraged. Every expression-marked token above MUST appear here with
 * its neutral value. A product's own unlayered tokens.css still beats this. */
@layer ds.expression {
  [data-ds-expression="practical"] {
    --ui-caret-shape-scale: 0;
    --ui-caret-nudge: 0;
  }
}
